public static long parseOctal(final byte[] buffer, final int offset, final int length) throws IOException {
    long result = 0;
    int end = offset + length;
    int start = offset;

    if (length < 2) {
        throw new IllegalArgumentException("Length " + length + " must be at least 2");
    }

    if (buffer[start] == 0) {
        return 0L;
    }

    // Skip leading spaces
    while (start < end) {
        if (buffer[start] == ' ') {
            start++;
        } else {
            break;
        }
    }

    // Trim all trailing NULs and spaces.
    byte trailer = buffer[end - 1];
    while (start < end && (trailer == 0 || trailer == ' ')) {
        end--;
        trailer = buffer[end - 1];
    }

    for (; start < end; start++) {
        final byte currentByte = buffer[start];
        if (currentByte == 0) {
            throw new IllegalArgumentException("Embedded NUL found at position " + start);
        }
        if (currentByte < '0' || currentByte > '7') {
            throw new IOException("Invalid octal character at position " + start + ": " + (char) currentByte);
        }
        result = (result << 3) + (currentByte - '0'); // Convert from ASCII
    }

    return result;
}

